public static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        while (bb.hasRemaining()) {
            int octet = bb.get() & 0xFF;
            if (octet < 128) {
                sb.append((char) octet);
                i++;
            } else if ((octet & 0xE0) == 0xC0) {
                int charValue = ((octet & 0x1F) << 6) | (bb.get() & 0x3F);
                sb.append((char) charValue);
                i += 2;
            } else if ((octet & 0xF0) == 0xE0) {
                int charValue = ((octet & 0x0F) << 12) | ((bb.get() & 0x3F) << 6) | (bb.get() & 0x3F);
                sb.append((char) charValue);
                i += 3;
            } else if ((octet & 0xF8) == 0xF0) {
                int charValue = ((octet & 0x07) << 18) | ((bb.get() & 0x3F) << 12) | ((bb.get() & 0x3F) << 6) | (bb.get() & 0x3F);
                sb.append((char) charValue);
                i += 4;
            } else {
                // Invalid UTF-8 octet
                throw new IllegalArgumentException("Invalid UTF-8 octet at index " + (i - 1));
            }
        }
        return i;
    } catch (BufferUnderflowException e) {
        throw new IllegalArgumentException("Buffer underflow at index " + i, e);
    }
}
