}

private static String performSubstitution(String value, Properties props) {
    if (value == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int startPos = 0;

    while (startPos < value.length()) {
        int leftBracket = value.indexOf("${", startPos);
        if (leftBracket == -1) {
            result.append(value.substring(startPos));
            break;
        }

        int rightBracket = value.indexOf("}", leftBracket + 2);
        if (rightBracket == -1) {
            result.append(value.substring(startPos));
            break;
        }

        result.append(value, startPos, leftBracket);
        String varName = value.substring(leftBracket + 2, rightBracket);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(varValue);
        } else {
            result.append(value, leftBracket, rightBracket + 1);
        }

        startPos = rightBracket + 1;
    }

    return result.toString();
}
