final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 1) {
        throw new IllegalArgumentException("Constant pool entry index must be greater than 0");
    }
    if (classFileBuffer == null || classFileBuffer.length == 0) {
        throw new IllegalArgumentException("Class file buffer must not be null or empty");
    }
    if (charBuffer == null || charBuffer.length == 0) {
        throw new IllegalArgumentException("Character buffer must not be null or empty");
    }

    int utf8Index = classFileBuffer.readUnsignedShort(constantPoolEntryIndex * 2);
    if (utf8Index < 1 || utf8Index > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid UTF-8 index in constant pool");
    }

    int utf8Length = classFileBuffer.readUnsignedByte(utf8Index);
    if (utf8Length > charBuffer.length) {
        throw new IllegalArgumentException("Character buffer is too small to hold UTF-8 string");
    }

    classFileBuffer.getChars(utf8Index + 1, utf8Length, charBuffer, 0);
    return new String(charBuffer, 0, utf8Length);
}
