import java.util.ArrayList;
import java.util.List;
import org.apache.commons.lang3.tuple.Pair;

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return Pair.of(new ArrayList<>(), 0L);
    }

    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long totalSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        totalSum += bounds.get(i);
        suffixSum.add(i == bounds.size() - 1 ? totalSum : suffixSum.get(suffixSum.size() - 1) + bounds.get(i));
    }

    // Reverse the suffix sum list to match the original order
    List<Integer> reversedSuffixSum = new ArrayList<>();
    for (int i = suffixSum.size() - 1; i >= 0; i--) {
        reversedSuffixSum.add(suffixSum.get(i));
    }

    return Pair.of(reversedSuffixSum, totalSum);
}

