private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<E> graph){
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();
    for (E edge : graph.getEdges()){
        Pair<Integer,Integer> endpoints = graph.getEndpoints(edge);
        List<Pair<Integer,Integer>> localSeparators = computeLocalSeparators(graph, endpoints);
        separatorList.add(new Pair<>(localSeparators, edge));
    }
    return separatorList;
}

private List<Pair<Integer,Integer>> computeLocalSeparators(Graph<E> graph, Pair<Integer,Integer> endpoints){
    List<Pair<Integer,Integer>> separators = new ArrayList<>();
    for (int commonNeighbor : getCommonNeighbors(graph, endpoints)){
        List<Pair<Integer,Integer>> sep = new ArrayList<>();
        sep.add(new Pair<>(endpoints.getValue0(), commonNeighbor));
        sep.add(new Pair<>(commonNeighbor, endpoints.getValue1()));
        separators.add(sep);
    }
    return separators;
}

private List<Integer> getCommonNeighbors(Graph<E> graph, Pair<Integer,Integer> endpoints){
    Set<Integer> neighbors1 = new HashSet<>(graph.getNeighbors(endpoints.getValue0()));
    Set<Integer> neighbors2 = new HashSet<>(graph.getNeighbors(endpoints.getValue1()));
    neighbors1.retainAll(neighbors2);
    return new ArrayList<>(neighbors1);
}
