private void pop(final String descriptor) {
    // Determine the number of arguments to pop based on the descriptor
    int numToPop = 0;
    for (char c : descriptor.toCharArray()) {
        switch (c) {
            case 'I': // int
            case 'J': // long
            case 'F': // float
            case 'D': // double
                numToPop += 1;
                break;
            case 'B': // byte
            case 'C': // char
            case 'S': // short
                numToPop += 1;
                break;
            case 'Z': // boolean
                numToPop += 1;
                break;
            case 'L': // reference
                // Skip over the class name
                int semiIndex = descriptor.indexOf(';', index);
                if (semiIndex == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                numToPop += 1;
                index = semiIndex + 1;
                break;
            case '[': // array
                numToPop += 1;
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }

    // Pop the appropriate number of abstract types from the output frame stack
    for (int i = 0; i < numToPop; i++) {
        outputFrame.popAbstractType();
    }
}
